        if (maxSame < 4) continue;
        const score = maxSame * (el.querySelectorAll('a[href]').length > 0 ? 1.5 : 1) + Math.min(20, (el.innerText || '').length / 200);
        if (score > bestScore) { best = el; bestScore = score; }
